/* Minimal styling for playable snake game */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #111;
  color: #eee;
  font-family: monospace;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#game-container {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}

#score-display {
  font-size: 18px;
  margin-bottom: 8px;
  color: #0f0;
}

#game-canvas {
  border: 2px solid #444;
  background: #000;
  display: block;
}

#game-over {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(0, 0, 0, 0.85);
  padding: 30px 40px;
  text-align: center;
  border: 2px solid #f00;
  border-radius: 8px;
}

#game-over-text {
  font-size: 28px;
  color: #f00;
  margin-bottom: 10px;
}

#final-score {
  font-size: 18px;
  margin-bottom: 16px;
  color: #ff0;
}

#play-again-btn {
  padding: 10px 24px;
  font-size: 16px;
  font-family: monospace;
  background: #0f0;
  color: #000;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

#play-again-btn:hover {
  background: #0c0;
}

.hidden {
  display: none !important;
}

/**
 * Snake Game — Minimal Playable Version (Ticket 1)
 *
 * Game logic is separated from rendering.
 * Game state is exposed on `window.game` for debugging/testing.
 * The game loop is steppable via `window.game.step()`.
 */

(function () {
  "use strict";

  // ─── Constants ───────────────────────────────────────────────
  const BOARD_SIZE = 20;         // Fixed 20x20 grid
  const CELL_SIZE = 25;          // Pixels per cell
  const TICK_MS = 150;           // Movement interval (ms)
  const CANVAS_SIZE = BOARD_SIZE * CELL_SIZE; // 500px

  // Directions
  const DIR = {
    UP: { x: 0, y: -1 },
    DOWN: { x: 0, y: 1 },
    LEFT: { x: -1, y: 0 },
    RIGHT: { x: 1, y: 0 },
  };

  // Opposite directions (to prevent reversing)
  const OPPOSITE = {};
  OPPOSITE[DIR.UP.x + "," + DIR.UP.y] = DIR.DOWN;
  OPPOSITE[DIR.DOWN.x + "," + DIR.DOWN.y] = DIR.UP;
  OPPOSITE[DIR.LEFT.x + "," + DIR.LEFT.y] = DIR.RIGHT;
  OPPOSITE[DIR.RIGHT.x + "," + DIR.RIGHT.y] = DIR.LEFT;

  // ─── Game State ──────────────────────────────────────────────
  let snake;        // Array of {x, y} segments, index 0 = head
  let food;         // {x, y}
  let direction;    // Current movement direction
  let nextDirection; // Buffered direction (applied on next tick)
  let score;
  let gameOver;
  let tickInterval; // setInterval handle

  // ─── DOM Elements ────────────────────────────────────────────
  const canvas = document.getElementById("game-canvas");
  const ctx = canvas.getContext("2d");
  const scoreDisplay = document.getElementById("score-display");
  const gameOverEl = document.getElementById("game-over");
  const finalScoreEl = document.getElementById("final-score");
  const playAgainBtn = document.getElementById("play-again-btn");

  // Set canvas size
  canvas.width = CANVAS_SIZE;
  canvas.height = CANVAS_SIZE;

  // ─── Initialization ──────────────────────────────────────────

  /**
   * Reset all game state to initial values.
   */
  function initGame() {
    // Snake starts at center, length 3, heading right
    const startX = Math.floor(BOARD_SIZE / 2);
    const startY = Math.floor(BOARD_SIZE / 2);
    snake = [
      { x: startX, y: startY },
      { x: startX - 1, y: startY },
      { x: startX - 2, y: startY },
    ];
    direction = DIR.RIGHT;
    nextDirection = DIR.RIGHT;
    score = 0;
    gameOver = false;
    spawnFood();
    updateScoreDisplay();
    hideGameOver();
  }

  /**
   * Spawn food at a random empty cell.
   */
  function spawnFood() {
    let attempts = 0;
    while (attempts < BOARD_SIZE * BOARD_SIZE) {
      const x = Math.floor(Math.random() * BOARD_SIZE);
      const y = Math.floor(Math.random() * BOARD_SIZE);
      if (!isOnSnake(x, y)) {
        food = { x, y };
        return;
      }
      attempts++;
    }
    // Fallback: shouldn't happen on a 20x20 grid
    food = { x: 0, y: 0 };
  }

  /**
   * Check if a position is occupied by the snake.
   */
  function isOnSnake(x, y) {
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === x && snake[i].y === y) {
        return true;
      }
    }
    return false;
  }

  // ─── Game Loop ───────────────────────────────────────────────

  /**
   * Start the game loop with fixed tick rate.
   */
  function startGameLoop() {
    stopGameLoop();
    tickInterval = setInterval(tick, TICK_MS);
  }

  /**
   * Stop the game loop.
   */
  function stopGameLoop() {
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  /**
   * Single game tick — advance the snake one step.
   * This is also exposed as a steppable function for testing.
   */
  function tick() {
    if (gameOver) return;

    // Apply buffered direction
    direction = nextDirection;

    // Calculate new head position
    const head = snake[0];
    const newHead = {
      x: head.x + direction.x,
      y: head.y + direction.y,
    };

    // Check wall collision
    if (
      newHead.x < 0 ||
      newHead.x >= BOARD_SIZE ||
      newHead.y < 0 ||
      newHead.y >= BOARD_SIZE
    ) {
      endGame();
      return;
    }

    // Check self collision
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }

    // Move snake: prepend new head
    snake.unshift(newHead);

    // Check food
    if (newHead.x === food.x && newHead.y === food.y) {
      score++;
      updateScoreDisplay();
      spawnFood();
      // Don't remove tail — snake grows
    } else {
      // Remove tail to maintain length
      snake.pop();
    }

    render();
  }

  /**
   * End the game.
   */
  function endGame() {
    gameOver = true;
    stopGameLoop();
    showGameOver();
  }

  // ─── Input Handling ──────────────────────────────────────────

  /**
   * Handle keyboard input for direction changes.
   */
  function handleKeydown(e) {
    if (gameOver) return;

    let newDir = null;

    switch (e.key) {
      case "ArrowUp":
      case "w":
      case "W":
        newDir = DIR.UP;
        break;
      case "ArrowDown":
      case "s":
      case "S":
        newDir = DIR.DOWN;
        break;
      case "ArrowLeft":
      case "a":
      case "A":
        newDir = DIR.LEFT;
        break;
      case "ArrowRight":
      case "d":
      case "D":
        newDir = DIR.RIGHT;
        break;
    }

    if (newDir) {
      e.preventDefault();
      // Prevent reversing into self
      const key = newDir.x + "," + newDir.y;
      if (OPPOSITE[key] !== direction) {
        nextDirection = newDir;
      }
    }
  }

  // ─── Rendering ───────────────────────────────────────────────

  /**
   * Render the entire game state to the canvas.
   */
  function render() {
    // Clear canvas
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

    // Draw grid lines (faint)
    ctx.strokeStyle = "#1a1a1a";
    ctx.lineWidth = 1;
    for (let i = 0; i <= BOARD_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, CANVAS_SIZE);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(CANVAS_SIZE, i * CELL_SIZE);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = "#f00";
    ctx.fillRect(
      food.x * CELL_SIZE + 1,
      food.y * CELL_SIZE + 1,
      CELL_SIZE - 2,
      CELL_SIZE - 2
    );

    // Draw snake
    for (let i = 0; i < snake.length; i++) {
      const seg = snake[i];
      ctx.fillStyle = i === 0 ? "#0f0" : "#0a0";
      ctx.fillRect(
        seg.x * CELL_SIZE + 1,
        seg.y * CELL_SIZE + 1,
        CELL_SIZE - 2,
        CELL_SIZE - 2
      );
    }
  }

  // ─── UI Helpers ──────────────────────────────────────────────

  function updateScoreDisplay() {
    scoreDisplay.textContent = "Score: " + score;
  }

  function showGameOver() {
    finalScoreEl.textContent = "Final Score: " + score;
    gameOverEl.classList.remove("hidden");
  }

  function hideGameOver() {
    gameOverEl.classList.add("hidden");
  }

  // ─── Event Listeners ─────────────────────────────────────────

  document.addEventListener("keydown", handleKeydown);

  playAgainBtn.addEventListener("click", function () {
    initGame();
    startGameLoop();
    render();
  });

  // ─── Public API (for testing) ────────────────────────────────

  window.game = {
    init: initGame,
    tick: tick,
    render: render,
    get state() {
      return {
        snake: snake.map((s) => ({ ...s })),
        food: food ? { ...food } : null,
        direction: direction,
        nextDirection: nextDirection,
        score: score,
        gameOver: gameOver,
        boardSize: BOARD_SIZE,
        cellSize: CELL_SIZE,
      };
    },
  };

  // ─── Start ───────────────────────────────────────────────────

  initGame();
  startGameLoop();
  render();
})();

/**
 * Test script for Snake game logic (Ticket 1)
 * Tests game rules without DOM/browser
 */

// Simulate the game logic in Node.js
const BOARD_SIZE = 20;
const CELL_SIZE = 25;
const TICK_MS = 150;

const DIR = {
  UP: { x: 0, y: -1 },
  DOWN: { x: 0, y: 1 },
  LEFT: { x: -1, y: 0 },
  RIGHT: { x: 1, y: 0 },
};

const OPPOSITE = {};
OPPOSITE[DIR.UP.x + "," + DIR.UP.y] = DIR.DOWN;
OPPOSITE[DIR.DOWN.x + "," + DIR.DOWN.y] = DIR.UP;
OPPOSITE[DIR.LEFT.x + "," + DIR.LEFT.y] = DIR.RIGHT;
OPPOSITE[DIR.RIGHT.x + "," + DIR.RIGHT.y] = DIR.LEFT;

function isOnSnake(snake, x, y) {
  for (let i = 0; i < snake.length; i++) {
    if (snake[i].x === x && snake[i].y === y) return true;
  }
  return false;
}

function spawnFood(snake) {
  let attempts = 0;
  while (attempts < BOARD_SIZE * BOARD_SIZE) {
    const x = Math.floor(Math.random() * BOARD_SIZE);
    const y = Math.floor(Math.random() * BOARD_SIZE);
    if (!isOnSnake(snake, x, y)) return { x, y };
    attempts++;
  }
  return { x: 0, y: 0 };
}

function initGame() {
  const startX = Math.floor(BOARD_SIZE / 2);
  const startY = Math.floor(BOARD_SIZE / 2);
  const snake = [
    { x: startX, y: startY },
    { x: startX - 1, y: startY },
    { x: startX - 2, y: startY },
  ];
  let direction = DIR.RIGHT;
  let nextDirection = DIR.RIGHT;
  let score = 0;
  let gameOver = false;
  const food = spawnFood(snake);
  return { snake, direction, nextDirection, score, gameOver, food };
}

function tick(state) {
  if (state.gameOver) return state;

  state.direction = state.nextDirection;
  const head = state.snake[0];
  const newHead = {
    x: head.x + state.direction.x,
    y: head.y + state.direction.y,
  };

  // Wall collision
  if (
    newHead.x < 0 ||
    newHead.x >= BOARD_SIZE ||
    newHead.y < 0 ||
    newHead.y >= BOARD_SIZE
  ) {
    state.gameOver = true;
    return state;
  }

  // Self collision
  for (let i = 0; i < state.snake.length; i++) {
    if (state.snake[i].x === newHead.x && state.snake[i].y === newHead.y) {
      state.gameOver = true;
      return state;
    }
  }

  state.snake.unshift(newHead);

  if (newHead.x === state.food.x && newHead.y === state.food.y) {
    state.score++;
    state.food = spawnFood(state.snake);
  } else {
    state.snake.pop();
  }

  return state;
}

function changeDirection(state, newDir) {
  const key = newDir.x + "," + newDir.y;
  if (OPPOSITE[key] !== state.direction) {
    state.nextDirection = newDir;
  }
}

// ─── Tests ─────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    passed++;
  } else {
    failed++;
    console.error("FAIL:", message);
  }
}

// Test 1: Initial state
console.log("Test 1: Initial game state");
let s = initGame();
assert(s.snake.length === 3, "Snake starts with length 3");
assert(s.snake[0].x === 10 && s.snake[0].y === 10, "Head at center (10,10)");
assert(s.direction === DIR.RIGHT, "Initial direction is RIGHT");
assert(!s.gameOver, "Game not over initially");
assert(s.food !== undefined, "Food is spawned");
assert(!isOnSnake(s.snake, s.food.x, s.food.y), "Food not on snake");

// Test 2: Movement
console.log("Test 2: Snake movement");
s = initGame();
s = tick(s); // Move right
assert(s.snake[0].x === 11 && s.snake[0].y === 10, "Head moved right");
assert(s.snake.length === 3, "Length unchanged (no food eaten)");

// Test 3: Direction change
console.log("Test 3: Direction change");
s = initGame();
changeDirection(s, DIR.DOWN);
s = tick(s);
assert(s.snake[0].x === 10 && s.snake[0].y === 11, "Snake moved down after direction change");

// Test 4: Cannot reverse
console.log("Test 4: Cannot reverse direction");
s = initGame();
changeDirection(s, DIR.LEFT); // Try to go left while heading right
s = tick(s);
assert(s.snake[0].x === 11 && s.snake[0].y === 10, "Direction not reversed (still moved right)");

// Test 5: Eat food and grow
console.log("Test 5: Eat food and grow");
// Create a state where snake is next to food
s = initGame();
// Move snake to food position by placing food strategically
s.snake = [{ x: 5, y: 5 }, { x: 4, y: 5 }, { x: 3, y: 5 }];
s.direction = DIR.RIGHT;
s.nextDirection = DIR.RIGHT;
s.food = { x: 6, y: 5 };
s.score = 0;
s = tick(s);
assert(s.snake.length === 4, "Snake grew after eating food");
assert(s.score === 1, "Score incremented after eating food");

// Test 6: Wall collision
console.log("Test 6: Wall collision");
s = initGame();
// Move snake to right edge
s.snake = [{ x: 19, y: 10 }, { x: 18, y: 10 }, { x: 17, y: 10 }];
s.direction = DIR.RIGHT;
s.nextDirection = DIR.RIGHT;
s = tick(s);
assert(s.gameOver === true, "Game over on wall collision");

// Test 7: Self collision
console.log("Test 7: Self collision");
// Create a snake that will collide with itself
s = initGame();
s.snake = [
  { x: 10, y: 10 }, // head
  { x: 9, y: 10 },
  { x: 9, y: 11 },
  { x: 10, y: 11 },
  { x: 11, y: 11 },
  { x: 11, y: 10 },
];
s.direction = DIR.RIGHT;
s.nextDirection = DIR.RIGHT;
s.food = { x: 15, y: 15 };
s = tick(s);
assert(s.gameOver === true, "Game over on self collision");

// Test 8: Multiple ticks
console.log("Test 8: Multiple ticks");
s = initGame();
for (let i = 0; i < 5; i++) {
  s = tick(s);
}
assert(s.snake.length === 3, "Length still 3 after 5 ticks (no food)");
assert(s.snake[0].x === 15 && s.snake[0].y === 10, "Head at (15,10) after 5 right ticks");
assert(s.gameOver === false, "Game not over after 5 safe ticks");

// Summary
console.log("\n" + "=".repeat(50));
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failed === 0) {
  console.log("ALL TESTS PASSED ✓");
} else {
  console.log("SOME TESTS FAILED ✗");
  process.exit(1);
}

