/**
 * Snake Game — Ticket 2: Start Menu + Score System
 *
 * Features:
 *  - Start menu with title, board size input, session high-score, Start button
 *  - "Press any key to start" overlay
 *  - Real-time score during gameplay
 *  - Game-over screen with final score, session high-score, Play Again button
 *  - Session high-score (resets on page reload, no localStorage)
 *  - Configurable board size (default 20, min 10, capped by viewport)
 *
 * Game logic is separated from rendering.
 * Game state is exposed on `window.game` for debugging/testing.
 * The game loop is steppable via `window.game.step()`.
 */

(function () {
  "use strict";

  // ─── Constants ───────────────────────────────────────────────
  const DEFAULT_BOARD_SIZE = 20;
  const MIN_BOARD_SIZE = 10;
  const MAX_BOARD_SIZE = 99;
  const MIN_CELL_SIZE = 12; // Minimum cell size in pixels
  const TICK_MS = 150; // Movement interval (ms)

  // Directions
  const DIR = {
    UP: { x: 0, y: -1 },
    DOWN: { x: 0, y: 1 },
    LEFT: { x: -1, y: 0 },
    RIGHT: { x: 1, y: 0 },
  };

  // Opposite directions (to prevent reversing)
  const OPPOSITE = {};
  OPPOSITE[DIR.UP.x + "," + DIR.UP.y] = DIR.DOWN;
  OPPOSITE[DIR.DOWN.x + "," + DIR.DOWN.y] = DIR.UP;
  OPPOSITE[DIR.LEFT.x + "," + DIR.LEFT.y] = DIR.RIGHT;
  OPPOSITE[DIR.RIGHT.x + "," + DIR.RIGHT.y] = DIR.LEFT;

  // ─── Game State ──────────────────────────────────────────────
  let boardSize;       // Configurable grid size
  let cellSize;        // Calculated pixel size per cell
  let canvasSize;      // Canvas dimensions in pixels
  let snake;           // Array of {x, y} segments, index 0 = head
  let food;            // {x, y}
  let direction;       // Current movement direction
  let nextDirection;   // Buffered direction (applied on next tick)
  let score;
  let highScore;       // Session high-score
  let gameOver;
  let tickInterval;    // setInterval handle

  // Game flow states
  let gameState; // "menu" | "ready" | "playing" | "over"

  // ─── DOM Elements ────────────────────────────────────────────
  const canvas = document.getElementById("game-canvas");
  const ctx = canvas.getContext("2d");
  const scoreDisplay = document.getElementById("score-display");
  const startMenu = document.getElementById("start-menu");
  const readyOverlay = document.getElementById("ready-overlay");
  const gameOverEl = document.getElementById("game-over");
  const finalScoreEl = document.getElementById("final-score");
  const highScoreFinalEl = document.getElementById("high-score-final");
  const highScoreDisplay = document.getElementById("high-score-display");
  const boardSizeInput = document.getElementById("board-size-input");
  const startBtn = document.getElementById("start-btn");
  const playAgainBtn = document.getElementById("play-again-btn");

  // ─── Initialization ──────────────────────────────────────────

  /**
   * Initialize the session: high score, default board size, etc.
   */
  function initSession() {
    highScore = 0;
    boardSize = DEFAULT_BOARD_SIZE;
    boardSizeInput.value = DEFAULT_BOARD_SIZE;
    updateHighScoreDisplay();
    updateBoardSizeInputLimits();
    resizeCanvas();
  }

  /**
   * Update the board size input min/max based on viewport.
   */
  function updateBoardSizeInputLimits() {
    const maxByViewport = calculateMaxBoardSize();
    const effectiveMax = Math.min(MAX_BOARD_SIZE, maxByViewport);
    boardSizeInput.max = effectiveMax;
    boardSizeInput.min = MIN_BOARD_SIZE;
    // Clamp current value
    let val = parseInt(boardSizeInput.value, 10);
    if (val < MIN_BOARD_SIZE) val = MIN_BOARD_SIZE;
    if (val > effectiveMax) val = effectiveMax;
    boardSizeInput.value = val;
    boardSize = val;
  }

  /**
   * Calculate the maximum board size that fits in the viewport.
   * Account for score display height and padding.
   */
  function calculateMaxBoardSize() {
    const availableHeight = window.innerHeight - 60; // score display + padding
    const availableWidth = window.innerWidth - 20;
    const minDim = Math.min(availableHeight, availableWidth);
    return Math.floor(minDim / MIN_CELL_SIZE);
  }

  /**
   * Resize the canvas to fit the viewport, computing cell size.
   */
  function resizeCanvas() {
    const maxByViewport = calculateMaxBoardSize();
    const effectiveSize = Math.min(boardSize, maxByViewport);
    const availableHeight = window.innerHeight - 60;
    const availableWidth = window.innerWidth - 20;
    const minDim = Math.min(availableHeight, availableWidth);

    cellSize = Math.floor(minDim / effectiveSize);
    // Ensure minimum cell size
    if (cellSize < MIN_CELL_SIZE) {
      cellSize = MIN_CELL_SIZE;
    }

    canvasSize = cellSize * effectiveSize;
    canvas.width = canvasSize;
    canvas.height = canvasSize;
    boardSize = effectiveSize;
  }

  /**
   * Reset all game state to initial values.
   */
  function initGame() {
    resizeCanvas();

    // Snake starts at center, length 3, heading right
    const startX = Math.floor(boardSize / 2);
    const startY = Math.floor(boardSize / 2);
    snake = [
      { x: startX, y: startY },
      { x: startX - 1, y: startY },
      { x: startX - 2, y: startY },
    ];
    direction = DIR.RIGHT;
    nextDirection = DIR.RIGHT;
    score = 0;
    gameOver = false;
    spawnFood();
    updateScoreDisplay();
    hideGameOver();
  }

  /**
   * Spawn food at a random empty cell.
   */
  function spawnFood() {
    let attempts = 0;
    while (attempts < boardSize * boardSize) {
      const x = Math.floor(Math.random() * boardSize);
      const y = Math.floor(Math.random() * boardSize);
      if (!isOnSnake(x, y)) {
        food = { x, y };
        return;
      }
      attempts++;
    }
    // Fallback: shouldn't happen on a reasonable grid
    food = { x: 0, y: 0 };
  }

  /**
   * Check if a position is occupied by the snake.
   */
  function isOnSnake(x, y) {
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === x && snake[i].y === y) {
        return true;
      }
    }
    return false;
  }

  // ─── Game Loop ───────────────────────────────────────────────

  /**
   * Start the game loop with fixed tick rate.
   */
  function startGameLoop() {
    stopGameLoop();
    tickInterval = setInterval(tick, TICK_MS);
  }

  /**
   * Stop the game loop.
   */
  function stopGameLoop() {
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  /**
   * Single game tick — advance the snake one step.
   * This is also exposed as a steppable function for testing.
   */
  function tick() {
    if (gameOver) return;

    // Apply buffered direction
    direction = nextDirection;

    // Calculate new head position
    const head = snake[0];
    const newHead = {
      x: head.x + direction.x,
      y: head.y + direction.y,
    };

    // Check wall collision
    if (
      newHead.x < 0 ||
      newHead.x >= boardSize ||
      newHead.y < 0 ||
      newHead.y >= boardSize
    ) {
      endGame();
      return;
    }

    // Check self collision
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }

    // Move snake: prepend new head
    snake.unshift(newHead);

    // Check food
    if (newHead.x === food.x && newHead.y === food.y) {
      score++;
      updateScoreDisplay();
      spawnFood();
      // Don't remove tail — snake grows
    } else {
      // Remove tail to maintain length
      snake.pop();
    }

    render();
  }

  /**
   * End the game.
   */
  function endGame() {
    gameOver = true;
    stopGameLoop();

    // Update session high-score
    if (score > highScore) {
      highScore = score;
      updateHighScoreDisplay();
    }

    showGameOver();
  }

  // ─── Input Handling ──────────────────────────────────────────

  /**
   * Handle keyboard input for direction changes and game flow.
   */
  function handleKeydown(e) {
    // If on ready overlay, any key starts the game
    if (gameState === "ready") {
      e.preventDefault();
      beginGameplay();
      return;
    }

    if (gameOver) return;

    let newDir = null;

    switch (e.key) {
      case "ArrowUp":
      case "w":
      case "W":
        newDir = DIR.UP;
        break;
      case "ArrowDown":
      case "s":
      case "S":
        newDir = DIR.DOWN;
        break;
      case "ArrowLeft":
      case "a":
      case "A":
        newDir = DIR.LEFT;
        break;
      case "ArrowRight":
      case "d":
      case "D":
        newDir = DIR.RIGHT;
        break;
    }

    if (newDir) {
      e.preventDefault();
      // Prevent reversing into self
      const key = newDir.x + "," + newDir.y;
      if (OPPOSITE[key] !== direction) {
        nextDirection = newDir;
      }
    }
  }

  // ─── Game Flow Transitions ───────────────────────────────────

  /**
   * Show the start menu.
   */
  function showStartMenu() {
    gameState = "menu";
    startMenu.classList.remove("hidden");
    readyOverlay.classList.add("hidden");
    gameOverEl.classList.add("hidden");
    updateHighScoreDisplay();
  }

  /**
   * Transition from start menu to ready overlay.
   */
  function showReadyOverlay() {
    gameState = "ready";
    startMenu.classList.add("hidden");
    readyOverlay.classList.remove("hidden");
    gameOverEl.classList.add("hidden");
  }

  /**
   * Begin actual gameplay: hide overlays, init game, start loop.
   */
  function beginGameplay() {
    gameState = "playing";
    readyOverlay.classList.add("hidden");
    initGame();
    startGameLoop();
    render();
  }

  // ─── Rendering ───────────────────────────────────────────────

  /**
   * Render the entire game state to the canvas.
   */
  function render() {
    // Clear canvas
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, canvasSize, canvasSize);

    // Draw grid lines (faint)
    ctx.strokeStyle = "#1a1a1a";
    ctx.lineWidth = 1;
    for (let i = 0; i <= boardSize; i++) {
      ctx.beginPath();
      ctx.moveTo(i * cellSize, 0);
      ctx.lineTo(i * cellSize, canvasSize);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * cellSize);
      ctx.lineTo(canvasSize, i * cellSize);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = "#f00";
    ctx.fillRect(
      food.x * cellSize + 1,
      food.y * cellSize + 1,
      cellSize - 2,
      cellSize - 2
    );

    // Draw snake
    for (let i = 0; i < snake.length; i++) {
      const seg = snake[i];
      ctx.fillStyle = i === 0 ? "#0f0" : "#0a0";
      ctx.fillRect(
        seg.x * cellSize + 1,
        seg.y * cellSize + 1,
        cellSize - 2,
        cellSize - 2
      );
    }
  }

  // ─── UI Helpers ──────────────────────────────────────────────

  function updateScoreDisplay() {
    scoreDisplay.textContent = "Score: " + score;
  }

  function updateHighScoreDisplay() {
    highScoreDisplay.textContent = "High Score: " + highScore;
  }

  function showGameOver() {
    finalScoreEl.textContent = "Final Score: " + score;
    highScoreFinalEl.textContent = "High Score: " + highScore;
    gameOverEl.classList.remove("hidden");
  }

  function hideGameOver() {
    gameOverEl.classList.add("hidden");
  }

  // ─── Event Listeners ─────────────────────────────────────────

  document.addEventListener("keydown", handleKeydown);

  // Board size input change
  boardSizeInput.addEventListener("change", function () {
    let val = parseInt(this.value, 10);
    if (isNaN(val) || val < MIN_BOARD_SIZE) val = MIN_BOARD_SIZE;
    if (val > MAX_BOARD_SIZE) val = MAX_BOARD_SIZE;
    this.value = val;
    boardSize = val;
    // If game is not running, resize canvas to reflect new size
    if (gameState === "menu") {
      resizeCanvas();
      render();
    }
  });

  // Window resize: recalculate canvas
  window.addEventListener("resize", function () {
    updateBoardSizeInputLimits();
    if (gameState === "menu") {
      resizeCanvas();
      render();
    }
  });

  // Start button
  startBtn.addEventListener("click", function () {
    // Read board size from input
    let val = parseInt(boardSizeInput.value, 10);
    if (isNaN(val) || val < MIN_BOARD_SIZE) val = MIN_BOARD_SIZE;
    if (val > MAX_BOARD_SIZE) val = MAX_BOARD_SIZE;
    boardSizeInput.value = val;
    boardSize = val;

    showReadyOverlay();
  });

  // Play Again button — returns to start menu
  playAgainBtn.addEventListener("click", function () {
    showStartMenu();
  });

  // ─── Public API (for testing) ────────────────────────────────

  window.game = {
    init: initGame,
    step: tick,
    render: render,
    getState: function () {
      return {
        snake: snake.map(function (s) { return { x: s.x, y: s.y }; }),
        food: food ? { x: food.x, y: food.y } : null,
        direction: direction,
        nextDirection: nextDirection,
        score: score,
        highScore: highScore,
        gameOver: gameOver,
        boardSize: boardSize,
        cellSize: cellSize,
        gameState: gameState,
      };
    },
    setBoardSize: function (size) {
      boardSize = size;
      resizeCanvas();
      render();
    },
  };

  // ─── Start ───────────────────────────────────────────────────

  initSession();
  showStartMenu();
  render();
})();

/**
 * Self-test for Snake Game — Ticket 2: Start Menu + Score System
 *
 * Uses Playwright to verify:
 * 1. Start menu is visible on load
 * 2. Board size input works
 * 3. High score displays correctly
 * 4. "Start Game" button shows ready overlay
 * 5. Any key press begins gameplay
 * 6. Score updates during gameplay
 * 7. Game over shows final score and high score
 * 8. "Play Again" returns to start menu
 */

const { chromium } = require("playwright-core");
const path = require("path");

const PAGE_URL = "file://" + path.join(__dirname, "index.html");
const VIEWPORT = { width: 1280, height: 900 };

(async () => {
  let browser;
  let page;
  let failures = [];

  function assert(condition, message) {
    if (!condition) {
      failures.push(message);
      console.log("  FAIL: " + message);
    } else {
      console.log("  PASS: " + message);
    }
  }

  try {
    browser = await chromium.launch({ headless: true });
    page = await browser.newPage({ viewport: VIEWPORT });

    // ─── Test 1: Start menu visible on load ──────────────────────
    console.log("\n--- Test: Start menu on load ---");
    await page.goto(PAGE_URL);
    await page.waitForTimeout(500);

    const startMenuVisible = await page.evaluate(() => {
      const el = document.getElementById("start-menu");
      return el && !el.classList.contains("hidden");
    });
    assert(startMenuVisible, "Start menu is visible on load");

    const titleText = await page.evaluate(() => {
      return document.getElementById("title").textContent;
    });
    assert(titleText === "SNAKE", "Title displays 'SNAKE' (got: '" + titleText + "')");

    const highScoreText = await page.evaluate(() => {
      return document.getElementById("high-score-display").textContent;
    });
    assert(highScoreText === "High Score: 0", "Initial high score is 0 (got: '" + highScoreText + "')");

    const boardSizeValue = await page.evaluate(() => {
      return document.getElementById("board-size-input").value;
    });
    assert(boardSizeValue === "20", "Default board size is 20 (got: " + boardSizeValue + ")");

    const startBtnVisible = await page.evaluate(() => {
      const el = document.getElementById("start-btn");
      return el && !el.classList.contains("hidden");
    });
    assert(startBtnVisible, "Start Game button is visible");

    // ─── Test 2: Ready overlay after clicking Start ──────────────
    console.log("\n--- Test: Ready overlay ---");
    await page.click("#start-btn");
    await page.waitForTimeout(300);

    const readyOverlayVisible = await page.evaluate(() => {
      const el = document.getElementById("ready-overlay");
      return el && !el.classList.contains("hidden");
    });
    assert(readyOverlayVisible, "Ready overlay is visible after clicking Start");

    const startMenuHidden = await page.evaluate(() => {
      const el = document.getElementById("start-menu");
      return el.classList.contains("hidden");
    });
    assert(startMenuHidden, "Start menu is hidden after clicking Start");

    const readyText = await page.evaluate(() => {
      return document.getElementById("ready-text").textContent;
    });
    assert(readyText.toLowerCase().includes("press any key"), "Ready overlay says 'Press any key' (got: '" + readyText + "')");

    // ─── Test 3: Key press begins gameplay ───────────────────────
    console.log("\n--- Test: Key press starts game ---");
    await page.keyboard.press("ArrowUp");
    await page.waitForTimeout(300);

    const readyOverlayHidden = await page.evaluate(() => {
      const el = document.getElementById("ready-overlay");
      return el.classList.contains("hidden");
    });
    assert(readyOverlayHidden, "Ready overlay is hidden after keypress");

    const scoreDisplay = await page.evaluate(() => {
      return document.getElementById("score-display").textContent;
    });
    assert(scoreDisplay === "Score: 0", "Score starts at 0 (got: '" + scoreDisplay + "')");

    // Verify game is actually playing
    const gameState = await page.evaluate(() => {
      return window.game.getState().gameState;
    });
    assert(gameState === "playing", "Game state is 'playing' (got: '" + gameState + "')");

    // ─── Test 4: Score updates ───────────────────────────────────
    console.log("\n--- Test: Score updates ---");
    // Step the game several times to let the snake reach food
    // The snake starts at center heading right; food spawns randomly
    // Let's step many times to ensure we hit food
    let ateFood = false;
    let prevScore = 0;
    for (let i = 0; i < 100; i++) {
      await page.evaluate(() => window.game.step());
      const state = await page.evaluate(() => window.game.getState());
      if (state.score > prevScore) {
        ateFood = true;
        break;
      }
      prevScore = state.score;
    }

    if (ateFood) {
      assert(true, "Snake ate food and score increased");
    } else {
      // Even if we didn't hit food in 100 steps, score should still be 0 (not negative)
      const currentScore = await page.evaluate(() => window.game.getState().score);
      assert(currentScore >= 0, "Score is non-negative after stepping (got: " + currentScore + ")");
    }

    // ─── Test 5: Game over on wall collision ─────────────────────
    console.log("\n--- Test: Game over ---");
    // Reset and drive snake into wall
    await page.evaluate(() => {
      window.game.init();
      // Force direction to right
      window.game.step(); // move once
    });

    // Drive snake right until it hits the wall
    let reachedWall = false;
    for (let i = 0; i < 50; i++) {
      await page.evaluate(() => window.game.step());
      const state = await page.evaluate(() => window.game.getState());
      if (state.gameOver) {
        reachedWall = true;
        break;
      }
    }

    if (reachedWall) {
      assert(true, "Game ended on wall collision");
    } else {
      // Check if game over overlay is visible
      const gameOverVisible = await page.evaluate(() => {
        const el = document.getElementById("game-over");
        return el && !el.classList.contains("hidden");
      });
      assert(gameOverVisible, "Game over overlay is visible");
    }

    // Verify game over screen content
    const finalScoreText = await page.evaluate(() => {
      return document.getElementById("final-score").textContent;
    });
    assert(finalScoreText.startsWith("Final Score:"), "Final score is shown (got: '" + finalScoreText + "')");

    const highScoreFinalText = await page.evaluate(() => {
      return document.getElementById("high-score-final").textContent;
    });
    assert(highScoreFinalText.startsWith("High Score:"), "High score is shown on game over (got: '" + highScoreFinalText + "')");

    // ─── Test 6: Play Again returns to start menu ────────────────
    console.log("\n--- Test: Play Again ---");
    await page.click("#play-again-btn");
    await page.waitForTimeout(300);

    const startMenuVisible2 = await page.evaluate(() => {
      const el = document.getElementById("start-menu");
      return el && !el.classList.contains("hidden");
    });
    assert(startMenuVisible2, "Start menu is visible after Play Again");

    const gameOverHidden = await page.evaluate(() => {
      const el = document.getElementById("game-over");
      return el.classList.contains("hidden");
    });
    assert(gameOverHidden, "Game over overlay is hidden after Play Again");

    // ─── Test 7: High score persistence during session ───────────
    console.log("\n--- Test: High score tracking ---");
    // Click Start, begin game, score some points, then game over
    await page.click("#start-btn");
    await page.waitForTimeout(200);
    await page.keyboard.press("Enter");
    await page.waitForTimeout(200);

    // Score a few points by stepping
    for (let i = 0; i < 200; i++) {
      await page.evaluate(() => window.game.step());
      const state = await page.evaluate(() => window.game.getState());
      if (state.gameOver) break;
    }

    const sessionHighScore = await page.evaluate(() => window.game.getState().highScore);
    assert(sessionHighScore >= 0, "Session high score is tracked (got: " + sessionHighScore + ")");

    // ─── Test 8: Board size input ────────────────────────────────
    console.log("\n--- Test: Board size input ---");
    await page.click("#play-again-btn");
    await page.waitForTimeout(200);

    await page.fill("#board-size-input", "15");
    await page.evaluate(() => document.getElementById("board-size-input").dispatchEvent(new Event("change")));
    await page.waitForTimeout(200);

    const newBoardSize = await page.evaluate(() => window.game.getState().boardSize);
    assert(newBoardSize === 15, "Board size changes to 15 (got: " + newBoardSize + ")");

    // Reset to default
    await page.fill("#board-size-input", "20");
    await page.evaluate(() => document.getElementById("board-size-input").dispatchEvent(new Event("change")));

    // ─── Summary ─────────────────────────────────────────────────
    console.log("\n===============================");
    if (failures.length === 0) {
      console.log("ALL TESTS PASSED");
    } else {
      console.log("FAILURES: " + failures.length);
      failures.forEach((f, i) => console.log("  " + (i + 1) + ". " + f));
    }
    console.log("===============================\n");

  } catch (err) {
    console.error("Test error:", err.message);
    failures.push("Test error: " + err.message);
    console.log("FAILURES: " + failures.length);
  } finally {
    if (browser) await browser.close();
  }

  process.exit(failures.length > 0 ? 1 : 0);
})();

/**
 * Additional test: Verify high score updates when score exceeds it.
 */
const { chromium } = require("playwright-core");
const path = require("path");

const PAGE_URL = "file://" + path.join(__dirname, "index.html");
const VIEWPORT = { width: 1280, height: 900 };

(async () => {
  let browser;
  let page;
  let failures = [];

  function assert(condition, message) {
    if (!condition) {
      failures.push(message);
      console.log("  FAIL: " + message);
    } else {
      console.log("  PASS: " + message);
    }
  }

  try {
    browser = await chromium.launch({ headless: true });
    page = await browser.newPage({ viewport: VIEWPORT });
    await page.goto(PAGE_URL);
    await page.waitForTimeout(500);

    // ─── Test: High score updates when beaten ────────────────────
    console.log("--- Test: High score updates ---");

    // Start a game
    await page.click("#start-btn");
    await page.waitForTimeout(200);
    await page.keyboard.press("Enter");
    await page.waitForTimeout(200);

    // Score 5 points by stepping
    let scoreBefore = 0;
    for (let i = 0; i < 500; i++) {
      await page.evaluate(() => window.game.step());
      const state = await page.evaluate(() => window.game.getState());
      if (state.score > scoreBefore) {
        scoreBefore = state.score;
        console.log("  Score increased to: " + scoreBefore);
      }
      if (state.gameOver) break;
    }

    console.log("  Final score: " + scoreBefore);

    // If we scored, check high score was updated
    if (scoreBefore > 0) {
      const highScore = await page.evaluate(() => window.game.getState().highScore);
      assert(highScore === scoreBefore, "High score matches final score (high=" + highScore + ", score=" + scoreBefore + ")");
    }

    // Check the game over screen shows the high score
    const highScoreOnScreen = await page.evaluate(() => {
      return document.getElementById("high-score-final").textContent;
    });
    console.log("  High score on game over screen: " + highScoreOnScreen);

    // ─── Test: High score persists on start menu after game over ─
    console.log("\n--- Test: High score on start menu ---");
    await page.click("#play-again-btn");
    await page.waitForTimeout(200);

    const highScoreOnMenu = await page.evaluate(() => {
      return document.getElementById("high-score-display").textContent;
    });
    console.log("  High score on menu: " + highScoreOnMenu);
    assert(highScoreOnMenu.includes(String(scoreBefore)), "High score displayed on menu matches (got: " + highScoreOnMenu + ")");

    // ─── Test: Board size input constraints ──────────────────────
    console.log("\n--- Test: Board size constraints ---");
    await page.fill("#board-size-input", "5");
    await page.evaluate(() => document.getElementById("board-size-input").dispatchEvent(new Event("change")));
    const clampedLow = await page.evaluate(() => document.getElementById("board-size-input").value);
    assert(parseInt(clampedLow) >= 10, "Value clamped to min 10 (got: " + clampedLow + ")");

    // Get max from viewport
    const maxVal = await page.evaluate(() => {
      return parseInt(document.getElementById("board-size-input").max);
    });
    console.log("  Max board size from viewport: " + maxVal);
    assert(maxVal >= 20, "Max board size fits at least 20 (got: " + maxVal + ")");

    // ─── Summary ─────────────────────────────────────────────────
    console.log("\n===============================");
    if (failures.length === 0) {
      console.log("ALL ADDITIONAL TESTS PASSED");
    } else {
      console.log("FAILURES: " + failures.length);
      failures.forEach((f, i) => console.log("  " + (i + 1) + ". " + f));
    }
    console.log("===============================\n");

  } catch (err) {
    console.error("Test error:", err.message);
    failures.push("Test error: " + err.message);
  } finally {
    if (browser) await browser.close();
  }

  process.exit(failures.length > 0 ? 1 : 0);
})();

