   * Account for score display height and padding.
   */
  function calculateMaxBoardSize() {
    const availableHeight = window.innerHeight - 60; // score display + padding
    const availableWidth = window.innerWidth - 20;
    const minDim = Math.min(availableHeight, availableWidth);
    return Math.floor(minDim / MIN_CELL_SIZE);
  }

  /**
   * Resize the canvas to fit the viewport, computing cell size.
   */
  function resizeCanvas() {
    const maxByViewport = calculateMaxBoardSize();
    const effectiveSize = Math.min(boardSize, maxByViewport);
    const availableHeight = window.innerHeight - 60;
    const availableWidth = window.innerWidth - 20;
    const minDim = Math.min(availableHeight, availableWidth);

    cellSize = Math.floor(minDim / effectiveSize);
    // Ensure minimum cell size
    if (cellSize < MIN_CELL_SIZE) {
      cellSize = MIN_CELL_SIZE;
    }

    canvasSize = cellSize * effectiveSize;
    canvas.width = canvasSize;
    canvas.height = canvasSize;
    boardSize = effectiveSize;
  }

  /**
   * Reset all game state to initial values.
   */
  function initGame() {
    resizeCanvas();

    // Snake starts at center, length 3, heading right
    const startX = Math.floor(boardSize / 2);
    const startY = Math.floor(boardSize / 2);
    snake = [
      { x: startX, y: startY },
      { x: startX - 1, y: startY },
      { x: startX - 2, y: startY },
    ];
    direction = DIR.RIGHT;
    nextDirection = DIR.RIGHT;
    score = 0;
    gameOver = false;
    spawnFood();
    updateScoreDisplay();
    hideGameOver();
  }

  /**
   * Spawn food at a random empty cell.
   */
  function spawnFood() {
    let attempts = 0;
    while (attempts < boardSize * boardSize) {
      const x = Math.floor(Math.random() * boardSize);
      const y = Math.floor(Math.random() * boardSize);
      if (!isOnSnake(x, y)) {
        food = { x, y };
        return;
      }
      attempts++;
    }
    // Fallback: shouldn't happen on a reasonable grid
    food = { x: 0, y: 0 };
  }

  /**
   * Check if a position is occupied by the snake.
   */
  function isOnSnake(x, y) {
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === x && snake[i].y === y) {
        return true;
      }
    }
    return false;
  }

  // ─── Game Loop ───────────────────────────────────────────────

  /**
   * Start the game loop with fixed tick rate.
   */
  function startGameLoop() {
    stopGameLoop();
    tickInterval = setInterval(tick, TICK_MS);
  }

  /**
   * Stop the game loop.
   */
  function stopGameLoop() {
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  /**
   * Single game tick — advance the snake one step.
   * This is also exposed as a steppable function for testing.
   */
  function tick() {
    if (gameOver) return;

    // Apply buffered direction
    direction = nextDirection;

    // Calculate new head position
    const head = snake[0];
    const newHead = {
      x: head.x + direction.x,
      y: head.y + direction.y,
    };

    // Check wall collision
    if (
      newHead.x < 0 ||
      newHead.x >= boardSize ||
      newHead.y < 0 ||
      newHead.y >= boardSize
    ) {
      endGame();
      return;
    }

    // Check self collision
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }

    // Move snake: prepend new head
    snake.unshift(newHead);

    // Check food
    if (newHead.x === food.x && newHead.y === food.y) {
      score++;
      updateScoreDisplay();
      spawnFood();
      // Don't remove tail — snake grows
    } else {
      // Remove tail to maintain length
      snake.pop();
    }

    render();
  }

  /**
   * End the game.
   */
  function endGame() {
    gameOver = true;
    stopGameLoop();

    // Update session high-score
    if (score > highScore) {
      highScore = score;
      updateHighScoreDisplay();
    }

    showGameOver();
  }

  // ─── Input Handling ──────────────────────────────────────────

  /**
   * Handle keyboard input for direction changes and game flow.
   */
  function handleKeydown(e) {
    // If on ready overlay, any key starts the game
    if (gameState === "ready") {
      e.preventDefault();
      beginGameplay();
      return;
    }

    if (gameOver) return;

    let newDir = null;

    switch (e.key) {
      case "ArrowUp":
      case "w":
      case "W":
        newDir = DIR.UP;
        break;
      case "ArrowDown":
      case "s":
      case "S":
        newDir = DIR.DOWN;
        break;
      case "ArrowLeft":
      case "a":
      case "A":
        newDir = DIR.LEFT;
        break;
      case "ArrowRight":
      case "d":
      case "D":
        newDir = DIR.RIGHT;
        break;
    }

    if (newDir) {
      e.preventDefault();
      // Prevent reversing into self
      const key = newDir.x + "," + newDir.y;
      if (OPPOSITE[key] !== direction) {
        nextDirection = newDir;
      }
    }
  }

  // ─── Game Flow Transitions ───────────────────────────────────

  /**
   * Show the start menu.
   */
  function showStartMenu() {
    gameState = "menu";
    startMenu.classList.remove("hidden");
    readyOverlay.classList.add("hidden");
    gameOverEl.classList.add("hidden");
    updateHighScoreDisplay();
  }

  /**
   * Transition from start menu to ready overlay.
   */
  function showReadyOverlay() {
    gameState = "ready";
    startMenu.classList.add("hidden");
    readyOverlay.classList.remove("hidden");
    gameOverEl.classList.add("hidden");
  }

  /**
   * Begin actual gameplay: hide overlays, init game, start loop.
   */
  function beginGameplay() {
    gameState = "playing";
    readyOverlay.classList.add("hidden");
    initGame();
    startGameLoop();
    render();
  }

  // ─── Rendering ───────────────────────────────────────────────

  /**
   * Render the entire game state to the canvas.
   */
  function render() {
    // Clear canvas
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, canvasSize, canvasSize);

    // Draw grid lines (faint)
    ctx.strokeStyle = "#1a1a1a";
    ctx.lineWidth = 1;
    for (let i = 0; i <= boardSize; i++) {
      ctx.beginPath();
      ctx.moveTo(i * cellSize, 0);
      ctx.lineTo(i * cellSize, canvasSize);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * cellSize);
      ctx.lineTo(canvasSize, i * cellSize);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = "#f00";
    ctx.fillRect(
      food.x * cellSize + 1,
      food.y * cellSize + 1,
      cellSize - 2,
      cellSize - 2
    );

    // Draw snake
    for (let i = 0; i < snake.length; i++) {
      const seg = snake[i];
      ctx.fillStyle = i === 0 ? "#0f0" : "#0a0";
      ctx.fillRect(
        seg.x * cellSize + 1,
        seg.y * cellSize + 1,
        cellSize - 2,
        cellSize - 2
      );
    }
  }

  // ─── UI Helpers ──────────────────────────────────────────────

  function updateScoreDisplay() {
    scoreDisplay.textContent = "Score: " + score;
  }

  function updateHighScoreDisplay() {
    highScoreDisplay.textContent = "High Score: " + highScore;
  }

  function showGameOver() {
    finalScoreEl.textContent = "Final Score: " + score;
    highScoreFinalEl.textContent = "High Score: " + highScore;
    gameOverEl.classList.remove("hidden");
  }

  function hideGameOver() {
    gameOverEl.classList.add("hidden");
  }

  // ─── Event Listeners ─────────────────────────────────────────

  document.addEventListener("keydown", handleKeydown);

  // Board size input change
  boardSizeInput.addEventListener("change", function () {
    let val = parseInt(this.value, 10);
    if (isNaN(val) || val < MIN_BOARD_SIZE) val = MIN_BOARD_SIZE;
    if (val > MAX_BOARD_SIZE) val = MAX_BOARD_SIZE;
    this.value = val;
    boardSize = val;
    // If game is not running, resize canvas to reflect new size
    if (gameState === "menu") {
      resizeCanvas();
      render();
    }
  });

  // Window resize: recalculate canvas
  window.addEventListener("resize", function () {
    updateBoardSizeInputLimits();
    if (gameState === "menu") {
      resizeCanvas();
      render();
    }
  });

  // Start button
  startBtn.addEventListener("click", function () {
    // Read board size from input
    let val = parseInt(boardSizeInput.value, 10);
    if (isNaN(val) || val < MIN_BOARD_SIZE) val = MIN_BOARD_SIZE;
    if (val > MAX_BOARD_SIZE) val = MAX_BOARD_SIZE;
    boardSizeInput.value = val;
    boardSize = val;

    showReadyOverlay();
  });

  // Play Again button — returns to start menu
  playAgainBtn.addEventListener("click", function () {
    showStartMenu();
  });

  // ─── Public API (for testing) ────────────────────────────────

  window.game = {
    init: initGame,
    step: tick,
    render: render,
    getState: function () {
      return {
        snake: snake.map(function (s) { return { x: s.x, y: s.y }; }),
        food: food ? { x: food.x, y: food.y } : null,
        direction: direction,
        nextDirection: nextDirection,
        score: score,
        highScore: highScore,
        gameOver: gameOver,
        boardSize: boardSize,
        cellSize: cellSize,
        gameState: gameState,
      };
    },
    setBoardSize: function (size) {
      boardSize = size;
      resizeCanvas();
      render();
    },
  };

  // ─── Start ───────────────────────────────────────────────────

  initSession();
  showStartMenu();
  render();
})();

