      beginGameplay();
      return;
    }

    if (gameOver) return;

    let newDir = null;

    switch (e.key) {
      case "ArrowUp":
      case "w":
      case "W":
        newDir = DIR.UP;
        break;
      case "ArrowDown":
      case "s":
      case "S":
        newDir = DIR.DOWN;
        break;
      case "ArrowLeft":
      case "a":
      case "A":
        newDir = DIR.LEFT;
        break;
      case "ArrowRight":
      case "d":
      case "D":
        newDir = DIR.RIGHT;
        break;
    }

    if (newDir) {
      e.preventDefault();
      // Prevent reversing into self
      const key = newDir.x + "," + newDir.y;
      if (OPPOSITE[key] !== direction) {
        nextDirection = newDir;
      }
    }
  }

