  ctx.lineWidth = 1;
  for (let i = 0; i <= boardSize; i++) {
    ctx.beginPath();
    ctx.moveTo(i * cellSize, 0);
    ctx.lineTo(i * cellSize, canvasSize);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * cellSize);
    ctx.lineTo(canvasSize, i * cellSize);
    ctx.stroke();
  }

  // Draw food
  ctx.fillStyle = "#f00";
  ctx.fillRect(
    food.x * cellSize + 1,
    food.y * cellSize + 1,
    cellSize - 2,
    cellSize - 2
  );

  // Draw snake
  for (let i = 0; i < snake.length; i++) {
    const seg = snake[i];
    ctx.fillStyle = i === 0 ? "#0f0" : "#0a0";
    ctx.fillRect(
      seg.x * cellSize + 1,
      seg.y * cellSize + 1,
      cellSize - 2,
      cellSize - 2
    );
  }
}

