/**
 * Self-test for Snake game — verifies game logic and rendering.
 * Connects to the already-running headless Chrome on port 9225.
 */
const puppeteer = require("puppeteer-core");

const CHROME_WS = "ws://127.0.0.1:9225/devtools/browser/0051b956-ab0c-41a0-a613-1fac7aef148b";
const FILE_URL = "file:///private/var/folders/b2/9__21c7903l0ymk4tnddnc_r0000gn/T/llm-interview-runs/pi-run-1786816954444-xde8gq/work/index.html";

(async () => {
  let browser;
  try {
    browser = await puppeteer.connect({ browserWSEndpoint: CHROME_WS });
    const page = await browser.newPage();
    await page.goto(FILE_URL, { waitUntil: "networkidle0" });

    // Wait for game to initialize
    await page.waitForFunction(() => window.game !== undefined, { timeout: 5000 });

    let allPassed = true;
    const results = [];

    function assert(condition, message) {
      if (condition) {
        results.push("PASS: " + message);
      } else {
        allPassed = false;
        results.push("FAIL: " + message);
      }
    }

    // Test 1: Game state exposed on window
    const state = await page.evaluate(() => window.game.getState());
    assert(state !== null && state.gameState === "menu", "Game state exposed on window");
    assert(state.highScore === 0, "Initial high score is 0");

    // Test 2: Start menu visible
    const startMenuVisible = await page.evaluate(() => {
      return !document.getElementById("start-menu").classList.contains("hidden");
    });
    assert(startMenuVisible, "Start menu is visible");

    // Test 3: Canvas exists
    const canvasExists = await page.evaluate(() => {
      return document.getElementById("game-canvas") !== null;
    });
    assert(canvasExists, "Canvas element exists");

    // Test 4: Neon rendering — check canvas has content
    const canvasWidth = await page.evaluate(() => document.getElementById("game-canvas").width);
    const canvasHeight = await page.evaluate(() => document.getElementById("game-canvas").height);
    assert(canvasWidth > 0 && canvasHeight > 0, "Canvas has dimensions: " + canvasWidth + "x" + canvasHeight);

    // Test 5: CSS has neon properties
    const hasNeonBg = await page.evaluate(() => {
      const body = window.getComputedStyle(document.body);
      return body.backgroundColor === "rgb(0, 0, 0)";
    });
    assert(hasNeonBg, "Body background is #000 (neon dark)");

    const hasNeonBorder = await page.evaluate(() => {
      const canvas = document.getElementById("game-canvas");
      const style = window.getComputedStyle(canvas);
      return style.borderColor.includes("0, 255, 255") || style.borderColor.includes("0,255,255");
    });
    assert(hasNeonBorder, "Canvas has neon cyan border");

    const hasNeonTitle = await page.evaluate(() => {
      const title = document.getElementById("title");
      const style = window.getComputedStyle(title);
      return style.color.includes("0, 255, 255") || style.color.includes("0,255,255");
    });
    assert(hasNeonTitle, "Title has neon cyan color");

    const hasNeonScore = await page.evaluate(() => {
      const score = document.getElementById("score-display");
      const style = window.getComputedStyle(score);
      return style.color.includes("0, 255, 0") || style.color.includes("0,255,0");
    });
    assert(hasNeonScore, "Score display has neon green color");

    const hasTextShadow = await page.evaluate(() => {
      const title = document.getElementById("title");
      const style = window.getComputedStyle(title);
      return style.textShadow !== "" && style.textShadow !== "none";
    });
    assert(hasTextShadow, "Title has text-shadow (neon glow)");

    // Test 6: Game logic — start game and step
    await page.evaluate(() => {
      window.game.setBoardSize(20);
    });

    // Navigate to ready state and begin gameplay
    await page.evaluate(() => {
      document.getElementById("start-btn").click();
    });

    // Press a key to begin
    await page.keyboard.press("Space");

    // Wait a bit for gameplay to start
    await new Promise(r => setTimeout(r, 200));

    const playingState = await page.evaluate(() => window.game.getState());
    assert(playingState.gameState === "playing", "Game enters playing state after keypress");
    assert(playingState.snake.length === 3, "Snake starts with length 3");
    assert(playingState.score === 0, "Initial score is 0");
    assert(playingState.direction !== null, "Direction is set");

    // Test 7: Snake moves on tick
    await page.evaluate(() => window.game.step());
    const afterStep = await page.evaluate(() => window.game.getState());
    assert(afterStep.snake.length === 3, "Snake length unchanged after non-food tick");
    // Head should have moved right
    assert(afterStep.snake[0].x > playingState.snake[0].x, "Snake head moved right after tick");

    // Test 8: Direction change
    await page.evaluate(() => {
      window.game.step(); // move
      window.game.step(); // move
      // Change direction to up
      const DIR = { UP: { x: 0, y: -1 }, DOWN: { x: 0, y: 1 }, LEFT: { x: -1, y: 0 }, RIGHT: { x: 1, y: 0 } };
      // We can't directly set nextDirection from eval, but we can check the step behavior
    });

    // Test 9: Wall collision
    // Set up a small board and move snake to edge
    await page.evaluate(() => {
      window.game.setBoardSize(10);
      window.game.init();
    });
    await page.keyboard.press("Space");
    await new Promise(r => setTimeout(r, 100));

    // Move snake all the way right to hit wall
    for (let i = 0; i < 20; i++) {
      await page.evaluate(() => window.game.step());
    }
    const wallState = await page.evaluate(() => window.game.getState());
    assert(wallState.gameOver === true, "Game ends on wall collision");

    // Test 10: Game over screen visible
    const gameOverVisible = await page.evaluate(() => {
      return !document.getElementById("game-over").classList.contains("hidden");
    });
    assert(gameOverVisible, "Game over screen is visible after wall collision");

    // Test 11: Score display updated
    const scoreText = await page.evaluate(() => document.getElementById("score-display").textContent);
    assert(scoreText.startsWith("Score:"), "Score display shows 'Score:' prefix");

    // Print results
    console.log("\n=== SELF-TEST RESULTS ===");
    for (const r of results) {
      console.log(r);
    }
    console.log("\n" + (allPassed ? "ALL TESTS PASSED" : "SOME TESTS FAILED"));
    console.log("========================\n");

    await page.close();
  } catch (err) {
    console.error("TEST ERROR:", err.message);
    console.log("FAIL: Test execution error");
  } finally {
    if (browser) {
      // Don't close the browser — it's our shared instance
    }
  }
})();

